CREATE OR REPLACE FUNCTION public.propiedad_cd5a7d821b3e49a9a941a26c89e3cdf8(documento character varying, cant integer, pagina integer, fechaminima timestamp with time zone, fechamaxima timestamp with time zone, filtro character varying, codigo_exacto character varying, token character varying, parametros character varying[])
  RETURNS SETOF pedidoventa_pdvp
  LANGUAGE plpgsql
AS
$body$
declare
	direccion character varying ;
	ciudad character varying ;
	cantidad_zonas numeric;
	numero1 character varying;
	posicion1 integer;
	numero2 character varying;
	posicion2 integer;
	seccion1 character varying;
	seccion2 character varying;
	calle integer;
	carrera integer;
begin 
	ciudad = parametros[1];
	if(ciudad is null)then raise exception 'Revisa el parametro ciudad que se recibe sin ningun valor'; end if;
	
	DROP table IF EXISTS temp_zonas;
	
	CREATE TEMP TABLE temp_zonas AS
        select z.* from pedidoventa_pdvp z
		inner join campo_documento on (cdrc_documento = cpdv_llave and cdpf_codigo='CIUDAD')
	where cpdv_plantilla = '7bc93a7172654969afe1e22c965d6eac'
		and cpvc_valoropcion = ciudad;
	
	select count(*) into cantidad_zonas from temp_zonas;
	
	if (cantidad_zonas > 0) then
		if (cantidad_zonas = 1) then 
			return query(select * from temp_zonas);
		else
			direccion = parametros[2];
			if(direccion is null)then raise exception 'Revisa el parametro direccion que se recibe sin ningun valor' ; end if;
			select SUBSTRING(direccion,'([0-9]{1,3})') into numero1;
			if(numero1 is null)then raise exception 'Revisa la direccion no se encuentran numeros' ; end if;
			select POSITION(numero1 IN direccion) into posicion1;
			select SUBSTRING (direccion, (posicion1 +  LENGTH (numero1))) into seccion2;
			select SUBSTRING (seccion2,	'([0-9]{1,3})') into numero2;
			if(numero2 is null)then raise exception 'Revisa la direccion no se encuentran numeros' ; end if;
			select POSITION(numero2 IN seccion2) into posicion2;
			select SUBSTRING (seccion2, posicion2) into seccion2;
			select SUBSTRING (direccion, 1, (posicion1 + LENGTH (numero1) + posicion2)) into seccion1;
			if( select seccion1 like '%C%L%')then
				calle:= numero1::int;
				carrera:= numero2::int;
				if(select seccion1 like '% SUR%')then
					calle := calle*-1;
				end if;
			else
				carrera:= numero1::int;
				calle:= numero2::int;
				if(select seccion2 like '% SUR%')then
					calle := calle*-1;
				end if;
			end if;
			return query (select zona_real.* from pedidoventa_pdvp zona_real
				inner join temp_zonas on (temp_zonas.cpdv_llave = zona_real.cpdv_llave)
				inner join campo_documento cp_cl_min on (cp_cl_min.cdrc_documento = zona_real.cpdv_llave and cp_cl_min.cdpf_codigo='CALLE_MINIMA')
				inner join campo_documento cp_cl_max on (cp_cl_max.cdrc_documento = zona_real.cpdv_llave and cp_cl_max.cdpf_codigo='CALLE_MAXIMA')
				inner join campo_documento cp_cr_min on (cp_cr_min.cdrc_documento = zona_real.cpdv_llave and cp_cr_min.cdpf_codigo='CARRERA_MINIMA')
				inner join campo_documento cp_cr_max on (cp_cr_max.cdrc_documento = zona_real.cpdv_llave and cp_cr_max.cdpf_codigo='CARRERA_MAXIMA')
			where cp_cl_min.mpvc_valornumero <= calle
				and cp_cl_max.mpvc_valornumero >= calle
				and cp_cr_min.mpvc_valornumero <= carrera
				and cp_cr_max.mpvc_valornumero >= carrera);
		end if;
	end if;

	DROP TABLE temp_zonas;
end
$body$
  VOLATILE
  COST 100
  ROWS 1000;
